/* Private conversations are never reused as public comments. No drafts in storage. */
(function(root){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=v=>{const d=new Date(v);return Number.isFinite(+d)?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not recorded';};
 const words=v=>String(v||'').replace(/^community_/,'').replaceAll('_',' ');
 const decision={published:'Approved and published',needs_information:'Clarification requested',declined:'Not selected',duplicate:'Marked duplicate',pending:'Returned to review'};
 function publicCards(s){
  if(!Array.isArray(s.public_comments)||!s.public_comments.length)return '';
  return '<aside class="thread-public-summary" aria-label="Public moderator comments"><strong>Moderator comments</strong>'+s.public_comments.map(m=>'<div><p class="thread-body">'+esc(m.body)+'</p><small>Site moderator · '+esc(date(m.created_at))+'</small></div>').join('')+((s.public_comment_count||0)>s.public_comments.length?'<details data-public-thread="'+esc(s.id)+'"><summary>View all '+Number(s.public_comment_count)+' moderator comments</summary><div class="thread-public-more"></div></details>':'')+'<small class="thread-authority">Community moderation—not a Team17 statement.</small></aside>';
 }
 function entry(e,canModerate){
  if(e.kind==='version')return '<details class="thread-version"><summary>Submission wording · version '+Number(e.version)+' · '+esc(date(e.at))+'</summary><h4>'+esc(e.wording?.title)+'</h4><p class="thread-body">'+esc(e.wording?.problem)+'</p><p class="thread-body">'+esc(e.wording?.desired_outcome)+'</p></details>';
  if(e.kind==='event')return '<p class="thread-event"><time>'+esc(date(e.at))+'</time> · '+esc(decision[e.decision]||words(e.action))+' · v'+Number(e.version)+'</p>';
  return '<article class="thread-message '+(e.visibility==='public'?'thread-public':'')+'" data-message-id="'+esc(e.id)+'"><header><strong>'+esc(e.author_label)+(e.is_mine?' · you':'')+'</strong><span>'+ (e.visibility==='public'?(e.hidden?'Hidden public comment':'Public moderator comment'):'Private reply')+'</span></header><p class="thread-body">'+esc(e.body)+'</p><footer><time>'+esc(date(e.at))+'</time> · wording v'+Number(e.version)+(e.imported?' · Earlier saved reply; original send time unavailable':'')+'</footer>'+(canModerate&&e.visibility==='public'&&!e.hidden?'<button type="button" class="cb-text-button" data-hide-comment="'+esc(e.id)+'">Hide from public board</button>':'')+'</article>';
 }
 function mount({container,submission,moderator,rpc,isCurrent=()=>true,onDirty=()=>{},onBusy=()=>{},onRecord=()=>{}}){
  let disposed=false,busy=false,loading=false,seq=0,page=0,order='newest',attempt=null,uncertain=false;
  const live=()=>!disposed&&container.isConnected&&isCurrent();
  const find=id=>container.querySelector('#'+id);
  const draft=()=>!!(find('threadReply')?.value.trim()||find('threadPublicBody')?.value.trim());
  const mark=()=>onDirty(draft());
  const say=(text,bad=false)=>{if(live()){find('threadFeedback').textContent=text;find('threadFeedback').dataset.error=String(bad);}};
  const lock=value=>{busy=value;onBusy(value);for(const el of container.querySelectorAll('textarea,button,input,select'))el.disabled=value;};
  async function call(action,payload={}){let timeout;try{return await Promise.race([rpc(action,{id:submission.id,...payload}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('Timed out')),15000);})]);}finally{clearTimeout(timeout);}}
  container.innerHTML='<section class="submission-thread" aria-labelledby="threadHeading"><div class="thread-heading"><div><h3 id="threadHeading">Conversation &amp; history</h3><p>Private to the submitter and site moderators. Public comments are labeled separately.</p></div><button type="button" class="sg-button secondary" id="threadRefresh">Refresh conversation</button></div><div class="thread-toolbar"><label>Date order <select id="threadOrder"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label><span id="threadChecked"></span></div><p id="threadFeedback" class="auth-feedback" role="status" aria-live="polite"></p><div id="threadEntries" aria-live="polite"><p>Loading conversation…</p></div><div class="cb-pager" id="threadPager"></div><form id="threadReplyForm" class="sg-form thread-compose"><label for="threadReply">'+(moderator?'Reply to the submitter · private':'Reply to the moderators · private')+'</label><textarea id="threadReply" rows="3" maxlength="2000" required placeholder="Add context or ask a follow-up question. This reply will not appear on the Bulletin Board."></textarea><button class="sg-button" id="threadSend" type="submit">Send private reply</button><p class="cb-small">Replies do not use your daily submission allowance and do not change the submitted wording. No email notification is sent.</p></form>'+(moderator?'<details class="thread-public-compose"><summary>Add a public moderator comment</summary><p id="threadPublicHelp">Only deliberately posted public comments appear alongside an approved submission. The private conversation above stays private.</p><form id="threadPublicForm" class="sg-form"><label for="threadPublicBody">Comment for everyone to read</label><textarea id="threadPublicBody" maxlength="2000" rows="3" required placeholder="Explain the moderation decision or provide a community update. Do not copy private details."></textarea><label class="sg-check"><input id="threadPublicConsent" type="checkbox" required><span>This comment is for the public Bulletin Board, not a private reply.</span></label><button id="threadPublicSend" type="submit" class="sg-button">Post public comment</button></form></details>':'')+'<button id="threadCheck" type="button" class="sg-button secondary" hidden>Check whether my reply saved</button></section>';
  const update=row=>{if(!live()||!row||row.id!==submission.id)return;Object.assign(submission,row);onRecord(row);};
  const applyAccess=()=>{if(!live())return;const closed=submission.state==='withdrawn';find('threadReplyForm').hidden=closed;if(moderator){find('threadPublicForm').hidden=submission.state!=='published';find('threadPublicHelp').textContent=submission.state==='published'?'This comment appears publicly alongside the approved wording. The private conversation stays private.':'Approve this submission first, then return here to add a public comment. Existing private replies will not be published.';}};
  async function load(){
   if(!live()||busy)return;loading=true;const ticket=++seq;find('threadRefresh').disabled=true;
   try{const r=await call('read',{page,order});if(!live()||ticket!==seq)return;if(!r||!Array.isArray(r.entries))throw Error('Invalid conversation');update(r.submission);
    find('threadEntries').innerHTML=r.entries.length?r.entries.map(e=>entry(e,moderator)).join(''):'<p>No replies yet. Start the private conversation below.</p>';
    find('threadChecked').textContent='Checked '+date(r.checked_at);find('threadPager').innerHTML=r.total>30?'<button type="button" class="sg-button secondary" id="threadPrev" '+(page===0?'disabled':'')+'>Previous</button><span>Page '+(page+1)+' of '+Math.ceil(r.total/30)+'</span><button type="button" class="sg-button secondary" id="threadNext" '+((page+1)*30>=r.total?'disabled':'')+'>Next</button>':'';
    if(find('threadPrev'))find('threadPrev').onclick=()=>{page--;load();};if(find('threadNext'))find('threadNext').onclick=()=>{page++;load();};
    for(const b of container.querySelectorAll('[data-hide-comment]'))b.onclick=async()=>{if(busy||uncertain||!confirm('Hide this moderator comment from the public board? It remains in the private history.'))return;lock(true);try{const r=await call('hide_public_comment',{message_id:b.dataset.hideComment});update(r.submission);say('Public comment hidden. The private history is retained.');}catch(_){say('The hide action could not be confirmed. Refresh the conversation to check its status.',true);}finally{if(live()){lock(false);await load();}}};
    applyAccess();
   }catch(_){if(live()&&ticket===seq){find('threadEntries').innerHTML='<p>Conversation could not be loaded. This does not mean it is empty. Use Refresh conversation to try again.</p>';}}
   finally{loading=false;if(live())find('threadRefresh').disabled=false;}
  }
  async function send(action){
   if(busy||loading||uncertain||!live())return;const pub=action==='public_comment',input=find(pub?'threadPublicBody':'threadReply');const body=input.value.trim();if(!body)return;
   if(pub&&!confirm('Post this moderator comment for everyone to read? No private replies will be published.'))return;
   attempt={action,body,version:submission.version,request_id:crypto.randomUUID(),...(pub?{public_consent:true}:{})};
   lock(true);say(pub?'Posting public comment…':'Saving private reply…');
   try{const r=await call(action,attempt);if(!live())return;update(r.submission);input.value='';if(pub)find('threadPublicConsent').checked=false;mark();say((pub?'Public moderator comment posted.':'Private reply saved. Nothing was published.')+' Saved '+date(r.saved_at));attempt=null;page=0;}
   catch(e){if(live()){if(['42501','40001','22023'].includes(e?.code)){say((e.code==='40001'?'The submission changed. Refresh the conversation before sending.':'Reply was not accepted. Check your access and the submission status.')+' Your draft is still here.',true);attempt=null;}else{uncertain=true;find('threadCheck').hidden=false;say('The save could not be confirmed. Your draft is still here. Check whether it saved before trying again.',true);}}}
   finally{if(live()){lock(false);if(uncertain){find('threadSend').disabled=true;if(moderator)find('threadPublicSend').disabled=true;input.disabled=true;}else await load();}}
  }
  find('threadReplyForm').onsubmit=e=>{e.preventDefault();send('reply');};find('threadReply').oninput=mark;
  if(moderator){find('threadPublicForm').onsubmit=e=>{e.preventDefault();send('public_comment');};find('threadPublicBody').oninput=mark;}
  find('threadCheck').onclick=async()=>{if(busy||!attempt)return;lock(true);try{const r=await call('check',{request_id:attempt.request_id});if(!live())return;if(r){update(r.submission);find(attempt.action==='public_comment'?'threadPublicBody':'threadReply').value='';if(moderator)find('threadPublicConsent').checked=false;mark();say((r.visibility==='public'?'Public comment':'Private reply')+' was saved at '+date(r.saved_at)+'. No duplicate was sent.');}else say('No saved reply was found for that request. Your draft is preserved; you may send it again.');uncertain=false;attempt=null;find('threadCheck').hidden=true;}catch(_){say('The saved reply could not be checked. Keep this tab open; your draft is still here.',true);}finally{if(live()){lock(false);if(uncertain){find('threadSend').disabled=true;if(moderator)find('threadPublicSend').disabled=true;}else await load();}}};
  find('threadRefresh').onclick=()=>load();find('threadOrder').onchange=e=>{order=e.target.value;page=0;load();};
  applyAccess();load();
  return {hasDraft:draft,dispose(){disposed=true;seq++;},refresh:load};
 }
 function bindPublic({container,rpc,isCurrent=()=>true}){
  for(const d of container.querySelectorAll('[data-public-thread]')){let loaded=false,working=false,page=0;d.ontoggle=()=>{if(d.open&&!loaded)load();};async function load(){if(working)return;working=true;const box=d.querySelector('.thread-public-more');try{const r=await rpc('public',{id:d.dataset.publicThread,page,order:'newest'});if(!d.isConnected||!isCurrent())return;box.innerHTML=r.entries.map(e=>entry(e,false)).join('')+'<div class="cb-pager">'+(page?'<button type="button" data-prev>Previous</button>':'')+((page+1)*30<r.total?'<button type="button" data-next>More comments</button>':'')+'</div>';loaded=true;const prev=box.querySelector('[data-prev]'),next=box.querySelector('[data-next]');if(prev)prev.onclick=()=>{page--;load();};if(next)next.onclick=()=>{page++;load();};}catch(_){if(d.isConnected)box.textContent='Public comments could not be loaded. Close and reopen to retry.';}finally{working=false;}}}
 }
 root.HLLVThread=Object.freeze({mount,publicCards,bindPublic});
})(globalThis);
